{'code': "from qgis.utils import iface
from qgis.core import QgsVectorDataProvider
lyr = iface.activeLayer()
caps = lyr.dataProvider().capabilities()
flags = {}
for name in dir(QgsVectorDataProvider):
    v = getattr(QgsVectorDataProvider, name)
    if isinstance(v, int) and name[0].isupper():
        flags[name] = bool(caps & v)
interesting = {k: v for k, v in flags.items() if 'Curv' in k or 'Add' in k or 'Circular' in k or 'Geometry' in k}
result = {'caps': int(caps), 'interesting': interesting}"}

